// motion-tokens.js
export const DUR = { instant: 0.125, fast: 0.3, base: 0.5, slow: 1, cinematic: 1.5, pagePhase: 0.35, panel: 0.25, exit: 0.7, scrimIn: 0.6, ruleLong: 2, scrollTo: 2.5 };
export const EASE = { outExpo: 'expo.out', outCubic: 'power2.out', inOutCubic: 'power2.inOut', outSine: 'sine.out', inSine: 'sine.in', inOutSine: 'sine.inOut', inOutQuad: 'power1.inOut', outQuart: 'power3.out' };
export const STAGGER = { tight: 0.05, base: 0.1, loose: 0.2 };
export const DIST = { revealX: -10, exitX: 10, lineY: 100 };
export const LENIS = { lerp: 0, duration: 0.8, easing: (t) => 1 - Math.pow(1 - t, 4), smoothWheel: true, syncTouch: false };

