// motion-presets.js
import { gsap } from 'gsap';
import { SplitText } from 'gsap/SplitText';
gsap.registerPlugin(SplitText);
const reduce = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
gsap.defaults({ ease: 'expo.out', duration: 1 });

export function onceInView(el, cb, threshold = 0.05) {
  if (el.getBoundingClientRect().top < innerHeight) return cb();
  const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { io.disconnect(); cb(); } }, { threshold });
  io.observe(el);
}
export function revealRow(row) {
  const rule = row.querySelector('[data-rule]');
  const kids = row.querySelectorAll('[data-reveal]');
  if (reduce()) { gsap.set(rule, { scaleX: 1 }); gsap.set(kids, { opacity: 1, xPercent: 0 }); return; }
  gsap.set(rule, { scaleX: 0, transformOrigin: '0% 50%' });
  gsap.set(kids, { xPercent: -10, opacity: 0 });
  onceInView(row, () => {
    gsap.to(rule, { scaleX: 1, duration: 1.5 });
    gsap.to(kids, { xPercent: 0, opacity: 1, duration: 1, delay: 0.2, stagger: 0.1 });
  }, 0.05);
}
export function hideRow(row) {
  gsap.set(row.querySelector('[data-rule]'), { transformOrigin: '100% 50%' });
  return gsap.timeline().to(row.querySelector('[data-rule]'), { scaleX: 0, duration: 0.7 }, 0).to(row.querySelectorAll('[data-reveal]'), { xPercent: 10, opacity: 0, duration: 0.7 }, 0);
}
export async function revealHeading(el) {
  await document.fonts.ready;
  const s = SplitText.create(el, { type: 'lines', mask: 'lines' });
  if (reduce()) return;
  return gsap.from(s.lines, { yPercent: 100, duration: 1, stagger: 0.1 });
}
export const fadeIn = (el, d = 1) => gsap.fromTo(el, { opacity: 0 }, { opacity: 1, duration: reduce() ? 0.01 : d });
export const formCascade = (fields) => reduce() ? gsap.set(fields, { opacity: 1 }) : gsap.fromTo(fields, { xPercent: -10, opacity: 0 }, { xPercent: 0, opacity: 1, duration: 0.8, stagger: 0.05 });

