import { gsap } from 'gsap';
document.querySelectorAll('.acc').forEach((acc) => {
  const btn = acc.querySelector('.acc__trigger'), panel = acc.querySelector('.acc__panel'), fill = acc.querySelector('.acc__fill');
  const canHover = () => matchMedia('(hover: hover) and (min-width: 769px)').matches;
  const setFill = (on) => gsap.to(fill, { scaleY: on && canHover() && btn.getAttribute('aria-expanded') !== 'true' ? 1 : 0, transformOrigin: '50% 100%', duration: 0.3, ease: 'sine.out' });
  btn.addEventListener('pointerenter', () => setFill(true));
  btn.addEventListener('pointerleave', () => setFill(false));
  btn.addEventListener('click', () => {
    const open = btn.getAttribute('aria-expanded') !== 'true';
    btn.setAttribute('aria-expanded', String(open));
    setFill(false);
    gsap.to(panel, { height: open ? panel.scrollHeight : 0, duration: 0.5, ease: 'sine.out' });
  });
});

