  let trigger;
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  function open(from) {
    trigger = from; lenis?.stop(); root.hidden = false; addEventListener('keydown', onKey);
    gsap.fromTo(root, { backdropFilter: 'blur(0px)' }, { backdropFilter: 'blur(30px)', duration: 1, ease: 'sine.out' });
    gsap.fromTo(scrim, { opacity: 0 }, { opacity: 0.7, duration: 1, ease: 'sine.out', onComplete: () => closeBtn.focus() });
  }
  function close() {
    removeEventListener('keydown', onKey); lenis?.start();
    gsap.to(scrim, { opacity: 0, duration: 1, ease: 'sine.out' });
    gsap.to(root, { backdropFilter: 'blur(0px)', duration: 1, ease: 'sine.out', onComplete: () => { root.hidden = true; trigger?.focus(); } });
  }
  closeBtn.addEventListener('click', close);
  scrim.addEventListener('click', close);
