export function validateForm(form) {
  let first = null;
  form.querySelectorAll('.field').forEach((f) => {
    const input = f.querySelector('input,textarea,select'), err = f.querySelector('.field__error');
    const ok = input.checkValidity();
    f.dataset.invalid = String(!ok); input.setAttribute('aria-invalid', String(!ok));
    err.hidden = ok; err.textContent = ok ? '' : input.validationMessage;
    if (!ok && !first) first = input;
  });
