  let d = s - last; if (d > 0 && innerWidth > 768) d *= 0.5;
  hidden = Math.min(1, Math.max(0, hidden + d / h)); last = s;
  hdr.style.transform = `translate3d(0,${-h * hidden}px,0)`;
  document.documentElement.style.setProperty('--header-offset', `${h * (1 - hidden)}px`);
